test('vatSummary aggregates multiple invoices by rate', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 21% VAT
  });

