    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 11495
  });

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }], // 22990
  });

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 11495
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, []);
  const issued3 = issueInvoice(inv3.value, []);

  const result = dashboard([issued1.value, issued2.value, issued3.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.topCustomers.length, 3);
  // Sorted by due amount descending
  assert.equal(result.value.topCustomers[0].customerId, 'C-002');
  assert.equal(result.value.topCustomers[0].due, 22990);
  assert.equal(result.value.topCustomers[1].customerId, 'C-001');
  assert.equal(result.value.topCustomers[1].due, 11495);
  assert.equal(result.value.topCustomers[2].customerId, 'C-003');
  assert.equal(result.value.topCustomers[2].due, 11495);
});

test('dashboard limits top customers to 3', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: `C-${String(i).padStart(3, '0')}`,
      issueDate: '2025-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: i }],
    });
    const issued = issueInvoice(inv.value, []);
    invoices.push(issued.value);
  }

  const result = dashboard(invoices, '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.topCustomers.length, 3);
  // Top 3 should be C-005, C-004, C-003
  assert.equal(result.value.topCustomers[0].customerId, 'C-005');
  assert.equal(result.value.topCustomers[1].customerId, 'C-004');
  assert.equal(result.value.topCustomers[2].customerId, 'C-003');
});

test('dashboard aggregates multiple invoices from same customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 11495
  });

