test('overdueInvoices sorts by daysOverdue (most overdue first)', () => {
  // Invoice 1: issued 2025-01-01, dueDate 2025-01-15
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  // Invoice 2: issued 2025-01-10, dueDate 2025-01-24
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2025-0001']);
  assert.equal(issued2.ok, true);

  const result = overdueInvoices([issued2.value, issued1.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
  // Most overdue should be first (inv1 with 31 days overdue)
  assert.equal(result.value[0].dueDate, '2025-01-15');
  assert.equal(result.value[0].daysOverdue, 31);
  assert.equal(result.value[1].dueDate, '2025-01-24');
  assert.equal(result.value[1].daysOverdue, 22);
});

test('overdueInvoices includes number, customerId, dueDate, daysOverdue, due', () => {
  const inv = createInvoice({
