test('vatSummary handles multiple VAT rates', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 10 }, // 9% VAT
    ],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = vatSummary([issued.value]);

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
