    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }], // 21840 with discount (19000 - 950 = 18050, VAT 21% = 3790.5 -> 3791, total = 21841... wait)
  });

  const issued2 = issueInvoice(inv2.value, []);
  const partial2 = recordPayment(issued2.value, { amount: 10000, date: '2025-01-20' });

