test('dashboard handles mixed statuses', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const issued = issueInvoice(inv2.value, []);
  const paid = recordPayment(issued.value, { amount: 11495, date: '2025-01-20' });

  assert.equal(paid.ok, true);

  const result = dashboard([draft.value, paid.value], '2025-02-15');

  assert.equal(result.ok, true);
  assert.deepEqual(result.value.counts, {
    draft: 1,
    issued: 0,
    partially_paid: 0,
    paid: 1,
  });
  assert.equal(result.value.outstanding, 0);
});

test('dashboard returns DATE_INVALID for invalid asOf', () => {
  const result = dashboard([], 'invalid-date');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('dashboard with partial payments reduces outstanding', () => {
  const inv1 = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 10920 with discount
  });

  const issued1 = issueInvoice(inv1.value, []);
  const partial1 = recordPayment(issued1.value, { amount: 3000, date: '2025-01-20' });

  const inv2 = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }], // 21840 with discount (19000 - 950 = 18050, VAT 21% = 3790.5 -> 3791, total = 21841... wait)
  });

  const issued2 = issueInvoice(inv2.value, []);
  const partial2 = recordPayment(issued2.value, { amount: 10000, date: '2025-01-20' });

  assert.equal(partial1.ok, true);
  assert.equal(partial2.ok, true);

  const result = dashboard([partial1.value, partial2.value], '2025-02-15');

  assert.equal(result.ok, true);
  // inv1: 10920 - 3000 = 7920
  // inv2: qty 2 = 19000, discount 5% = 950, after = 18050, VAT 21% = 3790.5 -> 3790 (banker's rounding), total = 21840
  // 21840 - 10000 = 11840
  // Total outstanding: 7920 + 11840 = 19760
  assert.equal(result.value.outstanding, 19760);
});
